'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Selector, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './selector.css'

import { LockGlyph } from './glyphs'

/**
 * Selector: one value out of a set.
 *
 * Segmented, dropdown and stepper are the same selection rendered three ways,
 * so they are one component and one state machine, exactly as `choice` is
 * (BDS-010). Five components would mean five accessibility stories and five
 * sets of the same bug.
 *
 * Two facts are kept apart, because the attribute contract keeps them apart.
 * `presentation` is how the control looks: `segmented`, `dropdown`, `stepper`.
 * `interaction` is how it is worked: `tap`, `hold` or `swipe`. Hold-to-charge
 * and swipe-to-commit are not renderings, so they do not widen the presentation
 * list; every one of the three presentations can be tapped, held or swiped.
 *
 * The interaction attaches to whichever surface commits. In `segmented` and
 * `dropdown` that surface is the option itself: hold an option to charge it,
 * or swipe, where each direction is bound to one option in order. In `stepper`
 * there are no per-option surfaces, so the value face is held, and a swipe
 * left or right commits the previous or next option.
 *
 * It performs nothing. It does not fetch, persist, or decide whether the value
 * is right. The host settles the outcome and passes it back as `result`.
 */

export type SelectorPresentation = 'segmented' | 'dropdown' | 'stepper'

export type SelectorInteraction = 'tap' | 'hold' | 'swipe'

export type SelectorSwipe = 'right' | 'left' | 'up' | 'down'

export type SelectorSettled = 'correct' | 'wrong' | 'rewarded'

export type SelectorState = 'idle' | 'selected' | 'committed' | SelectorSettled

export interface SelectorOption {
  id: string
  label: string
  /** Optional supporting line. Never carries meaning that the label does not. */
  detail?: string
  /**
   * What this option won, already formatted and signed: `'+250'`, `'x2'`.
   * Rendered as a badge floating clear of the corner, and only when the option
   * settles `rewarded`. Host-formatted rather than a number, because the sign,
   * the separator and the unit are all the game's to decide. Same field, same
   * rule, as `ChoiceOption.reward`.
   */
  reward?: string
  /** Not available at all. Flat, no padlock. */
  disabled?: boolean
  /** Available later, not now. Keeps its shape and shows a padlock. */
  locked?: boolean
}

export interface SelectorResult {
  /** Which options settled which way. Absent ids are left unsettled. */
  [optionId: string]: SelectorSettled
}

export interface SelectorProps {
  options: SelectorOption[]
  /** How it looks. Does not change what it means or how it is announced. */
  presentation?: SelectorPresentation
  /** How it is worked. Orthogonal to the presentation. */
  interaction?: SelectorInteraction
  /** What is being chosen. Rendered as the group's accessible name. */
  label: string
  /**
   * Commit as soon as the player picks, with no separate confirm step. Applies
   * to `tap` only: a hold that has charged and a swipe that has landed are
   * already deliberate acts, so they always commit, and a stepper always needs
   * a separate commit because stepping past a value is not choosing it.
   */
  commitOnSelect?: boolean
  /** Milliseconds of hold to reach a full charge. */
  holdDuration?: number
  /** How many options one step of a stepper moves. */
  increment?: number
  /** Settled outcomes from the host. Presence of this switches to result states. */
  result?: SelectorResult
  /** Locks everything without settling, for a closed round. */
  closed?: boolean
  /** Not available at all. Goes flat, takes no focus. */
  disabled?: boolean
  /** Available later, not now. Keeps its shape, shows a padlock, stays focusable. */
  locked?: boolean

  onSelected?: (optionId: string) => void
  onCommitted?: (optionId: string) => void
  /** Fired on every charge tick, 0 to 100. Cues sound and haptics. */
  onCharge?: (optionId: string, charge: number) => void
  /** Fired once per settled option when `result` arrives. */
  onSettled?: (optionId: string, state: SelectorSettled) => void
}

/** Glyphs, because colour alone is not an answer. */
const GLYPH: Record<SelectorSettled, string> = { correct: '✓', wrong: '✕', rewarded: '★' }

// The padlock is `LockGlyph` from `@gamestage/glyphs`. It was a colour emoji,
// which ignored every colour token and changed silhouette per operating system
// (GSUI-103). The character is not repeated here: the gate greps the source for
// emoji, and a mention would read as a use.

const STATE_LABEL = {
  selected: 'selected',
  committed: 'locked in',
  correct: 'correct',
  wrong: 'wrong',
  rewarded: 'rewarded',
  charging: 'charging',
  locked: 'locked',
  disabled: 'unavailable',
} as const

/**
 * Directions are handed out in this order, so the affirmative swipe of every
 * swipe-card idiom lands on the first option. Past the fourth an option has no
 * direction and is reached by the keyboard or by another presentation.
 */
const SWIPE_ORDER: SelectorSwipe[] = ['right', 'left', 'up', 'down']

const SWIPE_KEY: Record<string, SelectorSwipe> = {
  ArrowRight: 'right',
  ArrowLeft: 'left',
  ArrowUp: 'up',
  ArrowDown: 'down',
}

/** Coarse enough that a tap with a shaky thumb is not read as a gesture. */
const SWIPE_THRESHOLD_PX = 48

/**
 * A fixed tick rather than a frame loop: the charge has to be assertable, and a
 * requestAnimationFrame loop cannot be advanced by a test's clock.
 */
const CHARGE_TICK_MS = 50

export function Selector({
  options,
  presentation = 'segmented',
  interaction = 'tap',
  label,
  commitOnSelect = false,
  holdDuration = 800,
  increment = 1,
  result,
  closed = false,
  disabled = false,
  locked = false,
  onSelected,
  onCommitted,
  onCharge,
  onSettled,
}: SelectorProps) {
  const [selected, setSelected] = React.useState<string | undefined>(undefined)
  const [committed, setCommitted] = React.useState(false)
  const [charge, setCharge] = React.useState(0)
  const [chargingId, setChargingId] = React.useState<string | undefined>(undefined)
  const [open, setOpen] = React.useState(false)
  const [focusIndex, setFocusIndex] = React.useState(0)

  const optionRefs = React.useRef<(HTMLButtonElement | null)[]>([])
  const triggerRef = React.useRef<HTMLButtonElement | null>(null)
  const chargeRef = React.useRef(0)
  const timerRef = React.useRef<ReturnType<typeof setInterval> | undefined>(undefined)
  const dragRef = React.useRef<{ x: number; y: number } | null>(null)
  const settledAlready = React.useRef(new Set<string>())

  // The host settles. Report each outcome once, so a re-render does not replay
  // the sound.
  React.useEffect(() => {
    if (!result) return
    for (const [id, state] of Object.entries(result)) {
      if (settledAlready.current.has(id)) continue
      settledAlready.current.add(id)
      onSettled?.(id, state)
    }
  }, [result, onSettled])

  // A charge left running past unmount keeps firing onCharge into a component
  // that no longer exists.
  React.useEffect(() => stopCharging, [])

  const selectedIndex = options.findIndex((option) => option.id === selected)
  const currentIndex = selectedIndex >= 0 ? selectedIndex : 0
  const current = options[currentIndex]

  // A hold that has charged and a swipe that has landed are deliberate, so they
  // commit. A stepper never commits on selection: stepping past a value is not
  // choosing it, and an accidental commit two values early reads as a bug.
  const commits: 'separate' | 'immediate' =
    interaction === 'tap'
      ? commitOnSelect && presentation !== 'stepper'
        ? 'immediate'
        : 'separate'
      : 'immediate'

  const closedOut = committed || closed || !!result || disabled || locked

  function isDisabled(option: SelectorOption) {
    return !!option.disabled || disabled
  }

  function isBlocked(option: SelectorOption) {
    return isDisabled(option) || !!option.locked || closedOut
  }

  function stateOf(option: SelectorOption): SelectorState {
    const settled = result?.[option.id]
    if (settled) return settled
    if (option.id !== selected) return 'idle'
    return committed || closed ? 'committed' : 'selected'
  }

  // -- swipe ---------------------------------------------------------------
  // Which option each direction commits. For a stepper the directions are the
  // neighbours, which is the same fact the contract states: a direction, and so
  // the option it commits.
  const swipeTargets: Partial<Record<SelectorSwipe, string>> = {}
  if (interaction === 'swipe') {
    if (presentation === 'stepper') {
      const previous = options[currentIndex - increment]
      const next = options[currentIndex + increment]
      if (previous) swipeTargets.left = previous.id
      if (next) swipeTargets.right = next.id
    } else {
      options.forEach((option, index) => {
        const direction = SWIPE_ORDER[index]
        if (direction) swipeTargets[direction] = option.id
      })
    }
  }

  function swipeOf(optionId: string): SelectorSwipe | undefined {
    return SWIPE_ORDER.find((direction) => swipeTargets[direction] === optionId)
  }

  // -- acts ----------------------------------------------------------------
  function select(option: SelectorOption, commit: boolean) {
    if (isBlocked(option)) return
    setSelected(option.id)
    onSelected?.(option.id)
    if (commit) {
      setCommitted(true)
      onCommitted?.(option.id)
    }
  }

  function commitDirection(direction: SelectorSwipe) {
    const id = swipeTargets[direction]
    const option = options.find((candidate) => candidate.id === id)
    if (option) select(option, true)
  }

  function step(delta: number) {
    if (options.length === 0) return
    const next = Math.min(options.length - 1, Math.max(0, currentIndex + delta))
    const option = options[next]
    // A swipe is its own commit, and on a stepper the swipe is the step.
    if (option) select(option, interaction === 'swipe')
  }

  // -- hold ----------------------------------------------------------------
  function stopCharging() {
    if (timerRef.current !== undefined) {
      clearInterval(timerRef.current)
      timerRef.current = undefined
    }
  }

  function releaseHold() {
    stopCharging()
    chargeRef.current = 0
    setCharge(0)
    setChargingId(undefined)
  }

  function startHold(option: SelectorOption) {
    if (isBlocked(option) || timerRef.current !== undefined) return
    chargeRef.current = 0
    setCharge(0)
    setChargingId(option.id)
    const perTick = holdDuration > 0 ? (100 * CHARGE_TICK_MS) / holdDuration : 100
    timerRef.current = setInterval(() => {
      chargeRef.current = Math.min(100, chargeRef.current + perTick)
      setCharge(chargeRef.current)
      onCharge?.(option.id, Math.round(chargeRef.current))
      if (chargeRef.current >= 100) {
        releaseHold()
        select(option, true)
      }
    }, CHARGE_TICK_MS)
  }

  /**
   * The charge a surface renders. A committed hold stays at 100 rather than
   * snapping back, because the bar is the record of what the player did.
   */
  function chargeOf(option: SelectorOption): number | undefined {
    if (interaction !== 'hold') return undefined
    if (option.id === chargingId) return Math.round(charge)
    if (committed && option.id === selected) return 100
    return 0
  }

  function holdHandlers(option: SelectorOption) {
    if (interaction !== 'hold') return {}
    return {
      onPointerDown: () => startHold(option),
      onPointerUp: () => releaseHold(),
      onPointerLeave: () => releaseHold(),
      onPointerCancel: () => releaseHold(),
      onBlur: () => releaseHold(),
    }
  }

  /**
   * The keyboard equivalent of a hold. The design has not settled one, so this
   * is a decision rather than a specification: Space held charges, and Enter
   * commits outright. Space is the hold because a held key repeats and the
   * repeats are ignorable; Enter is there because a player who cannot hold a
   * key at all still has to be able to commit, and a control only one of them
   * can work is not keyboard operable.
   */
  function holdKeys(option: SelectorOption) {
    return {
      down(event: React.KeyboardEvent) {
        if (event.key === ' ') {
          event.preventDefault()
          if (!event.repeat) startHold(option)
          return true
        }
        if (event.key === 'Enter') {
          event.preventDefault()
          select(option, true)
          return true
        }
        return false
      },
      up(event: React.KeyboardEvent) {
        if (event.key === ' ') {
          event.preventDefault()
          releaseHold()
        }
      },
    }
  }

  // -- roving focus --------------------------------------------------------
  function moveFocus(to: number) {
    if (options.length === 0) return
    const next = (to + options.length) % options.length
    setFocusIndex(next)
    optionRefs.current[next]?.focus()
    // Arrow keys in a radiogroup move and select together. They only select
    // when a tap would have: a hold has not been held, and a swipe has its own
    // keys below.
    const option = options[next]
    if (interaction === 'tap' && option) select(option, commits === 'immediate')
  }

  function closeList(returnFocus = true) {
    setOpen(false)
    if (returnFocus) triggerRef.current?.focus()
  }

  React.useEffect(() => {
    if (presentation !== 'dropdown' || !open) return
    const index = selectedIndex >= 0 ? selectedIndex : 0
    setFocusIndex(index)
    optionRefs.current[index]?.focus()
  }, [open, presentation, selectedIndex])

  function optionKeyDown(option: SelectorOption, index: number) {
    return (event: React.KeyboardEvent) => {
      if (presentation === 'dropdown' && open) {
        if (event.key === 'Escape') {
          event.preventDefault()
          closeList()
          return
        }
        // Tabbing out closes it but does not claw the focus back: the player
        // asked to leave, and a list left open behind them is a control the
        // keyboard can land in again by accident.
        if (event.key === 'Tab') {
          closeList(false)
          return
        }
      }
      if (interaction === 'hold' && holdKeys(option).down(event)) return
      if (interaction === 'swipe' && presentation !== 'dropdown') {
        const direction = SWIPE_KEY[event.key]
        if (direction) {
          event.preventDefault()
          commitDirection(direction)
          return
        }
      }
      switch (event.key) {
        case 'ArrowRight':
        case 'ArrowDown':
          event.preventDefault()
          moveFocus(index + 1)
          break
        case 'ArrowLeft':
        case 'ArrowUp':
          event.preventDefault()
          moveFocus(index - 1)
          break
        case 'Home':
          event.preventDefault()
          moveFocus(0)
          break
        case 'End':
          event.preventDefault()
          moveFocus(options.length - 1)
          break
      }
    }
  }

  // -- pointer swipe, on the root so any surface of the control carries it ---
  const swipeSurface =
    interaction === 'swipe'
      ? {
          onPointerDown: (event: React.PointerEvent) => {
            dragRef.current = { x: event.clientX, y: event.clientY }
          },
          onPointerUp: (event: React.PointerEvent) => {
            const start = dragRef.current
            dragRef.current = null
            if (!start) return
            const dx = event.clientX - start.x
            const dy = event.clientY - start.y
            if (Math.max(Math.abs(dx), Math.abs(dy)) < SWIPE_THRESHOLD_PX) return
            const direction: SelectorSwipe =
              Math.abs(dx) >= Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : dy > 0 ? 'down' : 'up'
            commitDirection(direction)
          },
        }
      : {}

  // -- naming --------------------------------------------------------------
  // The accessible name carries the state, because a screen reader user gets no
  // fill, no stroke and no glyph. It also carries the gesture, because a hold
  // and a swipe are otherwise invisible.
  function nameOf(option: SelectorOption) {
    const words = [option.label]
    const state = stateOf(option)
    if (option.id === chargingId) words.push(STATE_LABEL.charging)
    else if (state !== 'idle') words.push(STATE_LABEL[state])
    // The reward badge is a drawing, so the amount has to be here too. Being
    // told you were rewarded without being told what with is worse than not
    // being told at all.
    if (state === 'rewarded' && option.reward) words.push(option.reward)
    if (option.locked) words.push(STATE_LABEL.locked)
    if (isDisabled(option)) words.push(STATE_LABEL.disabled)
    // A hint is for a surface at rest. Repeating 'hold to commit' at a
    // control already being held is noise at exactly the wrong moment.
    if (!isBlocked(option) && state === 'idle' && option.id !== chargingId) {
      if (interaction === 'hold') words.push('hold to commit')
      const direction = swipeOf(option.id)
      if (direction) words.push(`swipe ${direction}`)
    }
    return words.join(', ')
  }

  function optionMarkers(option: SelectorOption) {
    const state = stateOf(option)
    const settled = state === 'correct' || state === 'wrong' || state === 'rewarded'
    return (
      <>
        <span className="gs-selector__label" data-gs-scope="selector" data-gs-part="label">
          {option.label}
        </span>
        {option.detail ? <span className="gs-selector__detail">{option.detail}</span> : null}
        {interaction === 'hold' ? (
          <span
            className="gs-selector__charge"
            data-gs-scope="selector" data-gs-part="charge"
            data-gs-animates="emphasis"
            aria-hidden="true"
          >
            <span
              className="gs-selector__charge-fill"
              style={{ width: `${chargeOf(option) ?? 0}%` }}
            />
          </span>
        ) : null}
        {option.locked ? (
          <span className="gs-selector__glyph" data-gs-scope="selector" data-gs-part="glyph" aria-hidden="true">
            <LockGlyph />
          </span>
        ) : settled ? (
          <span
            className="gs-selector__glyph"
            data-gs-scope="selector" data-gs-part="glyph"
            data-gs-animates="emphasis"
            aria-hidden="true"
          >
            {GLYPH[state as SelectorSettled]}
          </span>
        ) : null}
        {/* The amount won, floating clear of the corner rather than sitting
            inside the control (BDS-012, specimen 2b). Hidden, because `nameOf`
            already carries it. `delta` is the part vocabulary's word for a
            signed change, which is what this is. */}
        {state === 'rewarded' && option.reward ? (
          <span
            className="gs-selector__reward"
            data-gs-scope="selector" data-gs-part="delta"
            data-gs-animates="emphasis"
            aria-hidden="true"
          >
            {option.reward}
          </span>
        ) : null}
      </>
    )
  }

  function optionAttributes(option: SelectorOption) {
    const state = stateOf(option)
    const settled = state === 'correct' || state === 'wrong' || state === 'rewarded'
    return {
      'data-gs-choice': option.id,
      'data-gs-selected': state === 'selected' ? 'true' : undefined,
      'data-gs-committed': state === 'committed' ? 'true' : undefined,
      'data-gs-state': settled ? state : undefined,
      'data-gs-disabled': isDisabled(option) ? 'true' : undefined,
      'data-gs-locked': option.locked || locked ? 'true' : undefined,
      'data-gs-charge': chargeOf(option),
      'data-gs-swipe': swipeOf(option.id),
      'data-gs-elevation': 'raised' as const,
      // The surface moves on press. Its fill and glyph are emphasis and survive
      // reduced motion, which is how a player who cannot see movement still
      // gets the answer.
      'data-gs-animates': 'motion' as const,
    }
  }

  function renderOption(option: SelectorOption, index: number, inList: boolean) {
    const state = stateOf(option)
    const chosen = state === 'selected' || state === 'committed'
    const role = inList ? 'option' : interaction === 'tap' ? 'radio' : undefined
    return (
      <button
        key={option.id}
        ref={(node) => {
          optionRefs.current[index] = node
        }}
        type="button"
        className="gs-selector__option gs-action-type"
        {...optionAttributes(option)}
        role={role}
        aria-checked={role === 'radio' ? chosen : undefined}
        aria-selected={role === 'option' ? chosen : undefined}
        aria-pressed={role === undefined ? chosen : undefined}
        aria-label={nameOf(option)}
        aria-disabled={isBlocked(option) || undefined}
        disabled={isDisabled(option)}
        tabIndex={index === focusIndex ? 0 : -1}
        onFocus={() => setFocusIndex(index)}
        onClick={() => {
          if (interaction !== 'tap') return
          select(option, commits === 'immediate')
          if (inList) closeList()
        }}
        onKeyDown={optionKeyDown(option, index)}
        onKeyUp={interaction === 'hold' ? holdKeys(option).up : undefined}
        {...holdHandlers(option)}
      >
        {optionMarkers(option)}
      </button>
    )
  }

  // -- presentations -------------------------------------------------------
  function renderSegmented() {
    return (
      <div className="gs-selector__track" data-gs-scope="selector" data-gs-part="track">
        {options.map((option, index) => renderOption(option, index, false))}
      </div>
    )
  }

  function renderDropdown() {
    const chosen = current && selectedIndex >= 0 ? current : undefined
    const triggerWords = [label, chosen ? nameOf(chosen) : 'nothing selected']
    return (
      <>
        <button
          ref={triggerRef}
          type="button"
          className="gs-selector__trigger gs-action-type"
          data-gs-scope="selector" data-gs-part="trigger"
          data-gs-elevation="raised"
          data-gs-animates="motion"
          data-gs-disabled={disabled ? 'true' : undefined}
          data-gs-locked={locked ? 'true' : undefined}
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-label={triggerWords.join(', ')}
          aria-disabled={closedOut || undefined}
          disabled={disabled}
          onClick={() => {
            if (closedOut) return
            setOpen((wasOpen) => !wasOpen)
          }}
          onKeyDown={(event) => {
            if (closedOut) return
            if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
              event.preventDefault()
              setOpen(true)
            }
          }}
        >
          <span className="gs-selector__label" data-gs-scope="selector" data-gs-part="label">
            {chosen ? chosen.label : label}
          </span>
        </button>
        {open ? (
          <div
            className="gs-selector__list"
            data-gs-scope="selector" data-gs-part="list"
            data-gs-elevation="raised"
            role="listbox"
            aria-label={label}
          >
            {options.map((option, index) => renderOption(option, index, true))}
          </div>
        ) : null}
      </>
    )
  }

  function renderStepper() {
    const previous = options[currentIndex - increment]
    const next = options[currentIndex + increment]
    const hold = current ? holdKeys(current) : undefined
    return (
      <div className="gs-selector__track" data-gs-scope="selector" data-gs-part="track">
        <button
          type="button"
          className="gs-selector__step"
          data-gs-scope="selector" data-gs-part="decrement"
          data-gs-elevation="raised"
          data-gs-animates="motion"
          data-gs-swipe={interaction === 'swipe' && previous ? 'left' : undefined}
          aria-label={`previous ${label}`}
          aria-disabled={(closedOut || !previous) || undefined}
          disabled={disabled}
          onClick={() => step(-increment)}
        >
          <span aria-hidden="true">−</span>
        </button>
        <div
          className="gs-selector__face gs-action-type"
          data-gs-scope="selector" data-gs-part="face"
          data-gs-elevation="raised"
          data-gs-charge={current ? chargeOf(current) : undefined}
          data-gs-animates="motion"
          role="spinbutton"
          tabIndex={disabled ? -1 : 0}
          aria-label={label}
          aria-valuenow={options.length === 0 ? undefined : currentIndex + 1}
          aria-valuemin={1}
          aria-valuemax={options.length}
          aria-valuetext={current ? nameOf(current) : 'nothing selected'}
          aria-disabled={closedOut || undefined}
          onKeyDown={(event) => {
            if (interaction === 'hold' && current && hold?.down(event)) return
            switch (event.key) {
              case 'ArrowRight':
              case 'ArrowUp':
                event.preventDefault()
                step(increment)
                break
              case 'ArrowLeft':
              case 'ArrowDown':
                event.preventDefault()
                step(-increment)
                break
              case 'Home':
                event.preventDefault()
                step(-options.length)
                break
              case 'End':
                event.preventDefault()
                step(options.length)
                break
            }
          }}
          onKeyUp={interaction === 'hold' && hold ? hold.up : undefined}
          {...(current ? holdHandlers(current) : {})}
        >
          <span className="gs-selector__label" data-gs-scope="selector" data-gs-part="label">
            {current ? current.label : label}
          </span>
          {current?.detail ? <span className="gs-selector__detail">{current.detail}</span> : null}
          {interaction === 'hold' ? (
            <span
              className="gs-selector__charge"
              data-gs-scope="selector" data-gs-part="charge"
              data-gs-animates="emphasis"
              aria-hidden="true"
            >
              <span
                className="gs-selector__charge-fill"
                style={{ width: `${(current && chargeOf(current)) || 0}%` }}
              />
            </span>
          ) : null}
        </div>
        <button
          type="button"
          className="gs-selector__step"
          data-gs-scope="selector" data-gs-part="increment"
          data-gs-elevation="raised"
          data-gs-animates="motion"
          data-gs-swipe={interaction === 'swipe' && next ? 'right' : undefined}
          aria-label={`next ${label}`}
          aria-disabled={(closedOut || !next) || undefined}
          disabled={disabled}
          onClick={() => step(increment)}
        >
          <span aria-hidden="true">+</span>
        </button>
      </div>
    )
  }

  const selectedOption = options.find((option) => option.id === selected)

  return (
    <div
      className="gs-selector"
      data-gs-component="selector"
      data-gs-presentation={presentation}
      data-gs-interaction={interaction}
      data-gs-commits={commits}
      data-gs-increment={presentation === 'stepper' ? increment : undefined}
      data-gs-disabled={disabled ? 'true' : undefined}
      data-gs-locked={locked ? 'true' : undefined}
      data-gs-elevation="raised"
      role={presentation === 'segmented' && interaction === 'tap' ? 'radiogroup' : 'group'}
      aria-label={label}
      aria-disabled={closedOut || undefined}
      {...swipeSurface}
    >
      {presentation === 'segmented' ? renderSegmented() : null}
      {presentation === 'dropdown' ? renderDropdown() : null}
      {presentation === 'stepper' ? renderStepper() : null}

      {commits === 'separate' && !closedOut && selectedOption ? (
        <button
          type="button"
          className="gs-selector__commit gs-action-type gs-pressable"
          data-gs-scope="selector" data-gs-part="commit"
          data-gs-elevation="raised"
          data-gs-animates="motion"
          onClick={() => select(selectedOption, true)}
        >
          Lock it in
        </button>
      ) : null}
    </div>
  )
}

/* Selector. Every value comes from a token; nothing here is a literal colour. */

.gs-selector {
  display: grid;
  gap: var(--gs-space-3);
  position: relative;
  justify-items: stretch;
}

/* The track holds whatever the presentation lays out. Segments sit in a row,
   a stepper sits as minus, face, plus. */
.gs-selector__track {
  display: flex;
  align-items: stretch;
  gap: var(--gs-space-2);
}

.gs-selector[data-gs-presentation='stepper'] .gs-selector__track {
  align-items: center;
  justify-content: start;
}

/* -- the pressable surfaces ----------------------------------------------- */
/* Controls are raised (BDS-040), and a raised control never fades or darkens on
   press: it moves (BDS-013). */
.gs-selector__option,
.gs-selector__trigger,
.gs-selector__step,
.gs-selector__face,
.gs-selector__commit {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: var(--gs-space-1);
  position: relative;

  /* 48px is the smallest target a thumb reliably hits. */
  min-height: var(--gs-size-touch-min);
  padding: var(--gs-space-3) var(--gs-space-4);

  text-align: left;

  color: var(--gs-color-ink);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-control, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-raised);
  cursor: pointer;

  /* Only the movement is timed here. Fill, glyph and charge transitions live on
     the emphasis elements so they survive reduced motion. */
  transition: transform var(--gs-motion-press) ease-out,
              box-shadow var(--gs-motion-press) ease-out;
}

.gs-selector__option { flex: 1 1 0; }

.gs-selector__option:focus-visible,
.gs-selector__trigger:focus-visible,
.gs-selector__step:focus-visible,
.gs-selector__face:focus-visible,
.gs-selector__commit:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

.gs-selector__option:hover:not([aria-disabled='true']),
.gs-selector__trigger:hover:not([aria-disabled='true']),
.gs-selector__step:hover:not([aria-disabled='true']),
.gs-selector__face:hover:not([aria-disabled='true']) {
  border-color: var(--gs-color-edge-high);
}

.gs-selector__option:active:not([aria-disabled='true']),
.gs-selector__trigger:active:not([aria-disabled='true']),
.gs-selector__step:active:not([aria-disabled='true']),
.gs-selector__face:active:not([aria-disabled='true']) {
  transform: translateY(3px);
  box-shadow: var(--gs-depth-flat);
}

/* -- the stepper ---------------------------------------------------------- */
.gs-selector__step {
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  min-width: var(--gs-size-touch-min);
  padding: 0;
  font-size: var(--gs-size-icon-control);
}

.gs-selector__face {
  flex: 1 1 auto;
  min-width: var(--gs-size-action-large);
  align-items: center;
  text-align: center;
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
}

/* -- the dropdown --------------------------------------------------------- */
.gs-selector__trigger { width: 100%; }

.gs-selector__list {
  display: grid;
  gap: var(--gs-space-1);
  padding: var(--gs-space-2);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-floating);
}

/* -- selection and commitment --------------------------------------------- */
.gs-selector__option[data-gs-selected='true'],
.gs-selector__face[data-gs-charge]:not([data-gs-charge='0']) {
  border-color: var(--gs-color-selected);
  border-width: var(--gs-stroke-selected);
}

.gs-selector__option[data-gs-committed='true'] {
  border-color: var(--gs-color-selected);
  border-width: var(--gs-stroke-selected);
  box-shadow: var(--gs-depth-flat);
}

/* -- hold to charge ------------------------------------------------------- */
/* The charge is emphasis, not motion: it is a fill that reports progress, and a
   player under reduced motion still has to be able to see the hold landing. */
.gs-selector__charge {
  display: block;
  width: 100%;
  height: var(--gs-space-1);
  margin-top: var(--gs-space-1);
  background: var(--gs-color-muted);
  border-radius: var(--gs-radius-full);
  overflow: hidden;
}

.gs-selector__charge-fill {
  display: block;
  height: 100%;
  background: var(--gs-color-interactive);
  border-radius: var(--gs-radius-full);
  transition: width var(--gs-motion-emphasis) linear,
              background-color var(--gs-motion-emphasis) ease-out;
}

.gs-selector__option[data-gs-charge='100'] .gs-selector__charge-fill,
.gs-selector__face[data-gs-charge='100'] .gs-selector__charge-fill {
  background: var(--gs-color-positive);
}

/* -- swipe ---------------------------------------------------------------- */
/* The direction a surface commits is a fact a theme may want to draw, and it is
   the only thing that says which way to throw the card. */
.gs-selector[data-gs-interaction='swipe'] .gs-selector__option {
  touch-action: none;
}

.gs-selector__option[data-gs-swipe]::after {
  content: '';
  position: absolute;
  inset: auto var(--gs-space-2) var(--gs-space-2) auto;
  width: var(--gs-space-2);
  height: var(--gs-space-2);
  border-top: var(--gs-stroke-selected) solid var(--gs-color-ink-secondary);
  border-right: var(--gs-stroke-selected) solid var(--gs-color-ink-secondary);
}

.gs-selector__option[data-gs-swipe='right']::after { transform: rotate(45deg); }
.gs-selector__option[data-gs-swipe='left']::after  { transform: rotate(-135deg); }
.gs-selector__option[data-gs-swipe='up']::after    { transform: rotate(-45deg); }
.gs-selector__option[data-gs-swipe='down']::after  { transform: rotate(135deg); }

/* -- settled outcomes ----------------------------------------------------- */
/* Three things at once: the fill or stroke, a glyph, and the text (BDS-012). */
.gs-selector__option[data-gs-state='correct'] {
  background: var(--gs-color-positive);
  color: var(--gs-color-on-bright);
  border-color: var(--gs-color-positive-base);
}

.gs-selector__option[data-gs-state='wrong'] {
  background: var(--gs-color-surface);
  border-style: dashed;
  border-color: var(--gs-color-negative);
  color: var(--gs-color-ink-secondary);
}
.gs-selector__option[data-gs-state='wrong'] .gs-selector__label { text-decoration: line-through; }

/* Rewarded is a ring and a glow around the control, never a fill (BDS-012).
   `depth.reward` is both in one token. This used to fill with `color.reward`
   and switch the ink, which made it the same drawing as `correct` with a
   different hue: a reward read as a second kind of right answer rather than as
   something won, and the fill took the option's own colour away, which is what
   the design keeps. Same change as `choice`, for the same reason. */
.gs-selector__option[data-gs-state='rewarded'] {
  box-shadow: var(--gs-depth-reward);
  /* The ring, the glow and the badge all extend past the control's own box, and
     a segmented track puts the options shoulder to shoulder, so without this the
     neighbour painted after it covers them. */
  z-index: 1;
}

/* Outside the corner, not inside it: inside, the amount is another line of text
   competing with the label. The option is the positioned ancestor and neither
   `.gs-selector` nor `.gs-selector__track` clips. */
.gs-selector__reward {
  position: absolute;
  /* One step out rather than two, unlike `choice`: a segmented track's gap is
     `space-2`, so two steps would land the badge on top of the next option
     rather than in the gutter beside it. */
  top: calc(-1 * var(--gs-space-1));
  right: calc(-1 * var(--gs-space-1));
  padding: var(--gs-space-1) var(--gs-space-2);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: 1;
  color: var(--gs-color-on-bright);
  background: var(--gs-color-reward);
  border-radius: var(--gs-radius-full);
  box-shadow: var(--gs-depth-raised);
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* -- locked and disabled -------------------------------------------------- */
/* Locked keeps its shape and shows a padlock. Only disabled goes flat. */
.gs-selector__option[data-gs-locked='true'],
.gs-selector__trigger[data-gs-locked='true'] { cursor: not-allowed; }

.gs-selector__option[data-gs-disabled='true'],
.gs-selector__trigger[data-gs-disabled='true'],
.gs-selector[data-gs-disabled='true'] .gs-selector__step,
.gs-selector[data-gs-disabled='true'] .gs-selector__face {
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  border-color: var(--gs-color-disabled);
  box-shadow: var(--gs-depth-flat);
  cursor: not-allowed;
}

/* -- text ----------------------------------------------------------------- */
.gs-selector__label { font: inherit; }

.gs-selector__detail {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-ink-secondary);
  text-transform: none;
}

.gs-selector__glyph {
  position: absolute;
  top: var(--gs-space-2);
  right: var(--gs-space-2);
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* -- the separate commit -------------------------------------------------- */
/* The offset base collapses and the face travels down by the same amount, so
   the face lands where the base was. */
.gs-selector__commit {
  align-items: center;
  min-height: var(--gs-size-action);
  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: 0;
  box-shadow: var(--gs-depth-pressable);
}

.gs-selector__commit:hover { background: var(--gs-color-interactive-hover); }

.gs-selector__commit:active {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-pressable-pressed);
}
